        // 非当前保管人
        assertThat(destroy("mallory", uniqueKey("DES"), evidenceKey, "销毁").getResponse().getStatus())
                .isEqualTo(409);

        // 借出中（BORROWED）不可销毁
        Map<String, Object> loanBody = new LinkedHashMap<>();
